const express = require('express');
const db = require('../db');

const app = express();

app.get('/api/tenants/:tenantId/audit-logs', async (req, res) => {
  const { tenantId } = req.params;

  // Strictly enforce user membership and audit role in the requested tenant
  if (req.user.tenantId !== tenantId || !req.user.roles.includes('security_auditor')) {
    return res.status(403).json({ error: 'Forbidden: You do not belong to this tenant' });
  }

  const logs = await db('tenant_audit_logs').where({ tenant_id: tenantId }).limit(100);
  return res.json({ tenantId, logs });
});

module.exports = app;
